const modi = require('modi');

const bundle = new modi.MODI();
const tof = bundle.tofs[0];
const joystick = bundle.joysticks[0];
const motorA = bundle.motors[0];
const motorB = bundle.motors[0];

setInterval(() => {
    if (tof.distance < 20) {
        motorA.speed = -50;
        motorB.speed = 50;
    } else {
        if (joystick.up) {
            motorA.speed = 60;
            motorB.speed = -60;
        } else if (joystick.down) {
            motorA.speed = -60;
            motorB.speed = 60;
        } else if (joystick.left) {
            motorA.speed = 60;
            motorB.speed = 60;
        } else if (joystick.right) {
            motorA.speed = -60;
            motorB.speed = -60;
        } else {
            motorA.speed = 0;
            motorB.speed = 0;
        }
    }
}, 10);

