#include "modi.h"

int main() {
    modi_init();
    modi_tof tof = modi_get_tof(0);
    modi_joystick joystick = modi_get_joystick(0);
    modi_motor motorA = modi_get_motor(0);
    modi_motor motorB = modi_get_motor(0);

    while (1) {
        if (modi_tof_distance(tof) < 20) {
            modi_motor_set_speed(motorA, -50);
            modi_motor_set_speed(motorB, 50);
        } else {
            if (modi_joystick_up(joystick)) {
                modi_motor_set_speed(motorA, 60);
                modi_motor_set_speed(motorB, -60);
            } else if (modi_joystick_down(joystick)) {
                modi_motor_set_speed(motorA, -60);
                modi_motor_set_speed(motorB, 60);
            } else if (modi_joystick_left(joystick)) {
                modi_motor_set_speed(motorA, 60);
                modi_motor_set_speed(motorB, 60);
            } else if (modi_joystick_right(joystick)) {
                modi_motor_set_speed(motorA, -60);
                modi_motor_set_speed(motorB, -60);
            } else {
                modi_motor_set_speed(motorA, 0);
                modi_motor_set_speed(motorB, 0);
            }
        }
    }
    return 0;
}
